// The folder interface of the parts (format version 11): the generated files are current, every folder keeps the rules,
// and adding a part edits no shared file (a throwaway part in a copy of the package, wired by the generator alone).
import { describe, expect, test } from "bun:test";
import { cpSync, existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync, symlinkSync, writeFileSync, mkdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { join, relative, resolve } from "node:path";
import { run, readFolders, camel, NOT_PARTS, RESERVED_NAMES, SPEC_BEGIN, SPEC_END } from "../scripts/parts";
import { FOLDER_PART_DEFS, FOLDER_PART_NAMES, INLINE_PARTS, INLINE_PART_NAMES } from "../src/parts/generated/registry";
import { PART_LIMITS, PART_UNTRUSTED_LIMITS } from "../src/parts/generated/limits";
import { LIMITS, UNTRUSTED_LIMITS, PART_NAMES } from "../src/index";

const PKG = resolve(import.meta.dir, "..");
const PARTS = join(PKG, "src/parts");
const folders = readdirSync(PARTS).filter((n) => !NOT_PARTS.has(n) && statSync(join(PARTS, n)).isDirectory());
/** the folders with a part.ts (a fenced part) and the folders with an inline.ts (a part of a sentence) */
const fenced = folders.filter((n) => existsSync(join(PARTS, n, "part.ts"))), inlined = folders.filter((n) => existsSync(join(PARTS, n, "inline.ts")));
const GENERATED = ["src/parts/generated/registry.ts", "src/parts/generated/limits.ts", "src/parts/generated/react.tsx", "src/parts/generated/inline.tsx", "src/parts/generated/css.ts", "fixtures/parts/samples.dh.md"];

describe("parts: the generated files", () => {
  test("are current (run bun scripts/parts.ts) and every folder is complete", () => {
    const r = run(PKG, true);
    expect(r.problems).toEqual([]);
    expect(r.stale).toEqual([]);
  });
  test("say they are generated", () => {
    for (const f of GENERATED) expect(readFileSync(join(PKG, f), "utf8")).toContain("generated by scripts/parts.ts");
    expect(readFileSync(join(PKG, "SPEC.md"), "utf8")).toContain(SPEC_BEGIN);
  });
  test("list every folder, and only folders", () => {
    expect([...FOLDER_PART_NAMES as readonly string[]].sort()).toEqual([...fenced].sort());
    for (const n of fenced) { expect(FOLDER_PART_DEFS[n].name).toBe(n); expect((PART_NAMES as readonly string[]).includes(n)).toBe(true); }
    expect([...INLINE_PART_NAMES as readonly string[]].sort()).toEqual([...inlined].sort());
    expect(INLINE_PARTS.map((d) => d.name).sort()).toEqual([...inlined].sort());
  });
});

describe("parts: every folder keeps the rules", () => {
  const importsOf = (src: string) => [...src.matchAll(/^\s*import\s[^;]*?from\s+"([^"]+)"/gm)].map((m) => m[1]);
  for (const n of folders) {
    const at = join(PARTS, n);
    test(`${n}: part.ts, inline.ts and limits.ts load before the parser (no import of the shared parser, checks, Markdown or React)`, () => {
      for (const f of ["part.ts", "inline.ts"]) if (existsSync(join(at, f))) for (const i of importsOf(readFileSync(join(at, f), "utf8"))) expect(i).not.toMatch(/dh-lib|doccheck|document|markdown|react|\.\/view|inline-view/);
      expect(importsOf(readFileSync(join(at, "limits.ts"), "utf8"))).toEqual([]);
    });
    test(`${n}: caps named after the part, in both sets, the strict one no higher`, () => {
      const keys = Object.keys(PART_LIMITS).filter((k) => k.startsWith(camel(n)));
      expect(keys.length).toBeGreaterThan(0);
      for (const k of keys) {
        const a = (LIMITS as any)[k], b = (UNTRUSTED_LIMITS as any)[k];
        expect(Number.isInteger(a) && a > 0).toBe(true);
        expect(Number.isInteger(b) && b > 0 && b <= a).toBe(true);
        expect((PART_UNTRUSTED_LIMITS as any)[k]).toBe(b);
      }
    });
    test(`${n}: no HTML strings, eval or string timers in its code`, () => {
      for (const f of readdirSync(at).filter((x) => /\.tsx?$/.test(x) && !x.endsWith(".test.ts"))) {
        const src = readFileSync(join(at, f), "utf8");
        expect(src).not.toMatch(/innerHTML|dangerouslySetInnerHTML|outerHTML|insertAdjacentHTML|\beval\s*\(|new Function|document\.write|setTimeout\(\s*["'`]/);
      }
    });
    test(`${n}: style.css has one :root block of --${n}-* tokens and the same dark values in both dark blocks`, () => {
      const css = readFileSync(join(at, "style.css"), "utf8").replace(/\/\*[\s\S]*?\*\//g, "");
      expect(css.match(/(^|\n):root\s*\{/g)?.length).toBe(1);
      const forced = css.match(/:root\[data-theme="dark"\]\s*\{([^}]*)\}/);
      const media = css.match(/@media \(prefers-color-scheme: dark\)\s*\{\s*:root:not\(\[data-theme="light"\]\)\s*\{([^}]*)\}/);
      expect(forced && media && forced[1].trim() === media[1].trim()).toBe(true);
      for (const m of css.matchAll(/(--[\w-]+)\s*:/g)) expect(m[1].startsWith(`--${n}-`)).toBe(true);
      expect(css).not.toMatch(/#[0-9a-fA-F]{3,8}\b/);   // colours are the theme's tokens
    });
    test(`${n}: the npm packages it imports are dependencies at an exact version`, () => {
      const pkg = JSON.parse(readFileSync(join(PKG, "package.json"), "utf8"));
      for (const d of FOLDER_PART_DEFS[n]?.dependencies ?? []) expect(pkg.dependencies?.[d] ?? "").toMatch(/^\d+\.\d+\.\d+$/);
    });
  }
});

// every file under dir: relative path -> sha256
function snapshot(dir: string): Map<string, string> {
  const out = new Map<string, string>();
  const walk = (d: string) => { for (const n of readdirSync(d)) { const p = join(d, n); if (n === "node_modules") continue; if (statSync(p).isDirectory()) walk(p); else out.set(relative(dir, p), createHash("sha256").update(readFileSync(p)).digest("hex")); } };
  walk(dir);
  return out;
}

describe("parts: adding a part edits no shared file", () => {
  test("a throwaway part in a copy: only its folder and the generated files change, and parse() draws it", () => {
    const tmp = mkdtempSync(join(tmpdir(), "dh-parts-"));
    try {
      for (const p of ["src", "scripts", "fixtures", "SPEC.md", "package.json", "tsconfig.json"]) cpSync(join(PKG, p), join(tmp, p), { recursive: true });
      symlinkSync(join(PKG, "node_modules"), join(tmp, "node_modules"));
      const before = snapshot(tmp);
      // the throwaway part: the smallest folder the checklist allows
      const at = join(tmp, "src/parts/zz-probe");
      mkdirSync(join(at, "fixtures"), { recursive: true });
      const files: Record<string, string> = {
        "part.ts": `import { definePart } from "../types";\nexport default definePart<{ n: number }>({ name: "zz-probe", form: "fenced", steps: false, llmKind: "own", fences: [{ word: "txt", flag: "probe" }], chartKinds: ["probe-kind"],\n  parse: (input, ctx) => { ctx.budget.charge(1); return { n: input.body.split("\\n").length, lang: input.attrs.lang ?? "", fm: String(ctx.frontMatter?.title ?? "") }; },\n  llm: (d) => \`probe with \${d.n} lines\`, check: () => [] });\n`,
        "limits.ts": "export const LIMITS = { zzProbeLines: 10 };\nexport const UNTRUSTED_LIMITS: typeof LIMITS = { ...LIMITS };\n",
        "view.tsx": `import React from "react";\nimport type { PartViewProps } from "../types";\nexport default function ZzProbeView({ data }: PartViewProps<{ n: number }>) { return <p>{data.n}</p>; }\n`,
        "style.css": ":root { --zz-probe-ink: var(--ink); }\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) { --zz-probe-ink: var(--ink); }\n}\n:root[data-theme=\"dark\"] { --zz-probe-ink: var(--ink); }\n",
        "spec.md": "#### Zz probe\n\nA throwaway part.\n",
        "sample.md": "```zz-probe\none\ntwo\n```\n",
        // the probe is also a part of a sentence: it takes every "zzq" in a text (parts/inline.ts), with a cap read from its own limits
        "inline.ts": `import { defineInline } from "../inline";\nexport default defineInline<{ cap: number }, { at: number }>({ name: "zz-probe", prepare: (page) => ({ cap: page.limits.zzProbeLines }), llm: (d) => \`<\${d.at}>\`,\n  scan: (text, st, budget) => { const hits: { from: number; to: number; data: { at: number } }[] = []; for (let i = text.indexOf("zzq"); i >= 0 && hits.length < st.cap; i = text.indexOf("zzq", i + 3)) { budget.charge(1); hits.push({ from: i, to: i + 3, data: { at: i } }); } return hits; } });\n`,
        "inline-view.tsx": `import React from "react";\nimport type { InlineViewProps } from "../inline";\nexport default function ZzProbeInline({ text, data }: InlineViewProps<{ at: number }>) { return <b data-at={data.at}>{text}</b>; }\n`,
        "zz-probe.test.ts": "",
        "fixtures/good-one.dh.md": "# P\n\n```zz-probe\none\n```\n",
        "fixtures/hostile-one.dh.md": "# P\n\n```zz-probe\none\n```\n",
      };
      for (const [f, t] of Object.entries(files)) writeFileSync(join(at, f), t);
      const r = run(tmp, false);
      expect(r.problems).toEqual([]);
      const after = snapshot(tmp);
      const changed = [...after.keys()].filter((k) => before.get(k) !== after.get(k)).sort();
      const allowed = (k: string) => k.startsWith("src/parts/zz-probe/") || GENERATED.includes(k) || k === "SPEC.md";
      expect(changed.filter((k) => !allowed(k))).toEqual([]);
      expect(changed).toContain("src/parts/generated/registry.ts");
      // SPEC.md changed only between its markers
      const cut = (s: string) => { const a = s.indexOf(SPEC_BEGIN), b = s.indexOf(SPEC_END); return s.slice(0, a) + s.slice(b); };
      expect(cut(readFileSync(join(tmp, "SPEC.md"), "utf8"))).toBe(cut(readFileSync(join(PKG, "SPEC.md"), "utf8")));
      expect(readFileSync(join(tmp, "SPEC.md"), "utf8")).toContain("#### Zz probe");
      // the copy parses the new part with no shared file touched: its block, its LLM view and its caps
      const probe = Bun.spawnSync(["bun", "-e", `import { parse, LIMITS, PART_NAMES } from "./src/index"; const d = parse("# P\\n\\n\`\`\`zz-probe\\na\\nb\\n\`\`\`\\n", { path: "p.dh.md" }); console.log(JSON.stringify({ t: d.blocks[1].type, n: d.blocks[1].data?.n, llm: d.llm.includes("probe with 2 lines"), cap: LIMITS.zzProbeLines, named: PART_NAMES.includes("zz-probe"), fence: [parse("# P\\n\\n\`\`\`txt probe\\na\\n\`\`\`\\n").blocks[1], parse("# P\\n\\n\`\`\`txt\\na\\n\`\`\`\\n").blocks.map((b) => b.type).join()], kind: parse("# P\\n\\n\`\`\`chart\\ntitle: x\\nkind: \\"probe-kind\\"\\n\`\`\`\\n").blocks[1].type, chart: parse("# P\\n\\n\`\`\`chart\\nkind: bar\\n\`\`\`\\n").blocks[1].type, fm: parse("---\\ntitle: Hi\\n---\\n# P\\n\\n\`\`\`zz-probe\\na\\n\`\`\`\\n").blocks[1].data.fm, inl: parse("# P\\n\\nhello zzq and \`zzq\` and zzq", { path: "p.md" }).blocks[0].md[1].c.map((x) => x.t + ":" + (x.t === "ref" ? x.name + "=" + x.text : x.v)), inlLlm: parse("# P\\n\\nhello zzq", { path: "p.md" }).llm.includes("hello <") }));`], { cwd: tmp, env: { ...process.env } });
      expect(probe.stderr.toString()).toBe("");
      const got = JSON.parse(probe.stdout.toString());
      expect(got.fm).toBe("Hi"); // the page's front matter reaches the part's parse
      // its inline part: a ref node for each "zzq" in plain text, none inside code; the LLM view says <at>
      expect(got.inl).toEqual(["text:hello ", "ref:zz-probe=zzq", "text: and ", "code:zzq", "text: and ", "ref:zz-probe=zzq"]);
      expect(got.inlLlm).toBe(true);
      expect({ ...got, fence: undefined, kind: undefined, chart: undefined, fm: undefined, inl: undefined, inlLlm: undefined }).toEqual({ t: "zz-probe", n: 2, llm: true, cap: 10, named: true });
      // a part's fences: ```txt probe is the part (lang txt), ```txt stays code; its chart kind: a ```chart of that kind is the part
      expect([got.fence[0].type, got.fence[0].data.lang, got.fence[1]]).toEqual(["zz-probe", "txt", "markdown"]);
      expect([got.kind, got.chart]).toEqual(["zz-probe", "chart"]);
      // and the same generator refuses a folder that breaks the rules, by name
      writeFileSync(join(at, "limits.ts"), "export const LIMITS = { lines: 10 };\nexport const UNTRUSTED_LIMITS: typeof LIMITS = { ...LIMITS };\n");
      expect(readFolders(tmp).problems.join("\n")).toMatch(/the cap "lines" must start with "zzProbe"/);
    } finally {
      rmSync(tmp, { recursive: true, force: true });
    }
  }, 60_000);
});

describe("reserved part names", () => {
  test("a folder named svg or interactive is refused (core reference-only types)", () => {
    const { mkdtempSync, mkdirSync, rmSync } = require("node:fs") as typeof import("node:fs");
    const { tmpdir } = require("node:os") as typeof import("node:os");
    const root = mkdtempSync(join(tmpdir(), "dh-reserved-"));
    try {
      for (const n of RESERVED_NAMES) mkdirSync(join(root, "src/parts", n), { recursive: true });
      const { folders, problems } = readFolders(root);
      expect(folders.length).toBe(0);
      expect(problems.sort()).toEqual([...RESERVED_NAMES].sort().map((n) => `src/parts/${n}: "${n}" is a core reference-only type; a folder part may not take that name`));
    } finally { rmSync(root, { recursive: true, force: true }); }
  });
});
